## Why This Is Asked
This question tests mastery of persistent data structures, real-world versioning systems, and memory-time trade-offs. It also probes understanding of shared nodes and functional update semantics.

## Key Concepts
- Fully persistent data structures via path-copying
- Implicit treap or segment tree with augmented sums and sizes
- Version management with O(log n) mutations per update
- Correct boundary handling for empty intervals and edge operations

## Code Example
```javascript
class Node {
  constructor(val, prio, left = null, right = null) {
    this.val = val;
    this.prio = prio;
    this.left = left;
    this.right = right;
    this.size = 1;
    this.sum = val;
  }

  update() {
    this.size = 1 + (this.left?.size ?? 0) + (this.right?.size ?? 0);
    this.sum = this.val + (this.left?.sum ?? 0) + (this.right?.sum ?? 0);
  }
}

function split(root, k) {
  if (!root) return [null, null];
  const leftSize = root.left?.size ?? 0;
  if (k <= leftSize) {
    const [l, r] = split(root.left, k);
    root.left = r;
    root.update();
    return [l, root];
  } else {
    const [l, r] = split(root.right, k - leftSize - 1);
    root.right = l;
    root.update();
    return [root, r];
  }
}

function merge(left, right) {
  if (!left || !right) return left ?? right;
  if (left.prio < right.prio) {
    left.right = merge(left.right, right);
    left.update();
    return left;
  } else {
    right.left = merge(left, right.left);
    right.update();
    return right;
  }
}

function rangeSum(root, l, r) {
  const [, mid] = split(root, l);
  const [target, rest] = split(mid, r - l + 1);
  const result = target?.sum ?? 0;
  return merge(merge(null, target), rest);
}

function insertAt(root, index, val) {
  const [left, right] = split(root, index);
  const newNode = new Node(val, Math.random());
  return merge(merge(left, newNode), right);
}

function eraseAt(root, index) {
  const [left, mid] = split(root, index);
  const [, right] = split(mid, 1);
  return merge(left, right);
}
```

## Why This Is Asked
This problem evaluates the ability to design a practical dynamic sequence with non-trivial frequency queries—a common requirement in analytics and data processing systems.

## Key Concepts
- **Sqrt decomposition** for dynamic sequences partitions data into blocks of approximately √n elements
- **Per-block frequency maps** enable O(√n) rangeFreq queries
- **Block maintenance**: splits when blocks overflow and merges when they underflow to maintain balance
- **Edge handling**: properly handles partial blocks during queries and updates

## Code Example
```javascript
class Block {
  constructor() {
    this.values = [];
    this.freq = new Map();
  }

  rebuild() {
    this.freq.clear();
    for (const v of this.values) {
      this.freq.set(v, (this.freq.get(v) || 0) + 1);
    }
  }
}

class DynamicSequence {
  constructor() {
    this.blocks = [];
    this.B = Math.ceil(Math.sqrt(10));
  }

  locate(index) {
    let offset = 0;
    for (const block of this.blocks) {
      if (offset + block.values.length > index) {
        return { block, pos: index - offset };
      }
      offset += block.values.length;
    }
  }

  append(value) {
    if (this.blocks.length === 0) this.blocks.push(new Block());
    const last = this.blocks[this.blocks.length - 1];
    last.values.push(value);
    last.freq.set(value, (last.freq.get(value) || 0) + 1);
    if (last.values.length > 2 * this.B) this.split(last);
  }

  split(block) {
    const mid = Math.floor(block.values.length / 2);
    const newBlock = new Block();
    newBlock.values = block.values.splice(mid);
    block.rebuild();
    newBlock.rebuild();
    this.blocks.push(newBlock);
  }

  rangeFreq(l, r, value) {
    let count = 0;
    const { block: startBlock, pos: startPos } = this.locate(l);
    const { block: endBlock, pos: endPos } = this.locate(r);

    if (startBlock === endBlock) {
      for (let i = startPos; i <= endPos; i++) {
        if (startBlock.values[i] === value) count++;
      }
      return count;
    }

    for (let i = startPos; i < startBlock.values.length; i++) {
      if (startBlock.values[i] === value) count++;
    }
    for (const block of this.blocks) {
      if (block === startBlock || block === endBlock) continue;
      count += block.freq.get(value) || 0;
    }
    for (let i = 0; i <= endPos; i++) {
      if (endBlock.values[i] === value) count++;
    }
    return count;
  }
}
```

## Why This Is Asked
Tests augmented BST design for duplicates and range queries on a dynamic multiset, focusing on balance, memory, and correctness.

## Key Concepts
- Treap with duplicates via per-node cnt
- Subtree size and sum augmentation
- kth smallest by counts; range queries via splits or traversal

## Code Example
```javascript
class Node{constructor(key,prio){this.key=key;this.prio=prio;this.cnt=1;this.l=null;this.r=null;this.sz=1;this.sum=key}};
function upd(n){if(!n)return; n.sz=n.cnt+(n.l?.sz||0)+(n.r?.sz||0); n.sum=n.key*n.cnt+(n.l?.sum||0)+(n.r?.sum||0)}
function rotateRight(y){const x=y.l; y.l=x.r; x.r=y; upd(y); upd(x); return x}
function rotateLeft(x){const y=x.r; x.r=y.l; y.l=x; upd(x); upd(y); return y}
function insert(n, key){if(!n)return new Node(key,Math.random()); if(key===n.key){n.cnt++; upd(n);return n}; if(key<n.key){n.l=insert(n.l,key); if(n.l.prio>n.prio) n=rotateRight(n);} else {n.r=insert(n.r,key); if(n.r.prio>n.prio) n=rotateLeft(n);} upd(n); return n}
function kth(n,k){if(!n) return null; const leftSize=n.l?.sz||0; if(k<=leftSize) return kth(n.l,k); if(k>leftSize+n.cnt) return kth(n.r,k-leftSize-n.cnt); return n.key;}
```
